//! `sermofur_core::records` against the table that the .NET `RecordJson` produced
//! (`rust/tests/golden/records.json`, regenerated by `rust/tools/record-oracle`).

use serde::Serialize;
use serde_json::Value;
use sermofur_core::format::{DateTimeOffset, parse_json_text};
use sermofur_core::records::*;
use uuid::Uuid;

fn golden() -> Value {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../tests/golden/records.json"
    );
    serde_json::from_str(&std::fs::read_to_string(path).expect("golden file")).expect("JSON")
}

fn date(text: &str) -> DateTimeOffset {
    parse_json_text(text, |_| 0).expect("a date")
}

fn all<E: DotNetEnum>() -> Vec<E> {
    E::NAMES.iter().map(|(_, _, member)| *member).collect()
}

/// The values the oracle writes, in its order.
fn written() -> Vec<(&'static str, String)> {
    let id = Uuid::parse_str("0f8fad5b-d9cb-469f-a165-70867728950e").expect("GUID");
    let other = Uuid::parse_str("7c9e6679-7425-40de-944b-e07fc1f90ae7").expect("GUID");
    let at = date("2026-01-02T03:04:05.678+02:00");
    let utc = date("2026-11-06T20:00:00.1234567+00:00");
    let mut out: Vec<(&'static str, String)> = Vec::new();
    fn push<T: Serialize>(out: &mut Vec<(&'static str, String)>, kind: &'static str, value: &T) {
        out.push((kind, write(value).expect("written")));
    }
    for kind in all::<ScopeKind>() {
        let name = ScopeKind::NAMES
            .iter()
            .find(|(_, _, k)| *k == kind)
            .expect("name")
            .0;
        push(
            &mut out,
            "Scope",
            &Scope {
                id: format!("s-{name}"),
                kind,
                parent_id: (kind != ScopeKind::Workspace).then(|| "workspace".to_owned()),
                relative_path: (kind == ScopeKind::Repository).then(|| "src/app".to_owned()),
            },
        );
    }
    #[derive(Serialize)]
    #[serde(rename_all = "camelCase")]
    struct Configuration {
        schema_version: i32,
        instance_id: String,
        created_at: DateTimeOffset,
    }
    push(
        &mut out,
        "InstanceConfiguration",
        &Configuration {
            schema_version: 2,
            instance_id: id.hyphenated().to_string(),
            created_at: utc,
        },
    );
    let provenance = |origin, actor: &str, timestamp| Provenance {
        origin,
        actor: Some(actor.to_owned()),
        timestamp,
    };
    for actor in all::<ActorKind>() {
        push(
            &mut out,
            "Provenance",
            &provenance(actor, "john <a&b> 'x' `y` +", at),
        );
    }
    for category in all::<MemoryCategory>() {
        for volatility in all::<Volatility>() {
            push(
                &mut out,
                "ClaimContent",
                &ClaimContent {
                    text: Some("Le café \"noir\" \u{e9}t\u{e9} \u{1F600}\n\t".to_owned()),
                    category,
                    volatility,
                    last_verified: (category == MemoryCategory::Decisions).then_some(at),
                    review_after: (volatility == Volatility::Volatile).then_some(utc),
                },
            );
        }
    }
    for kind in all::<EvidenceKind>() {
        let source = kind == EvidenceKind::SourceCode;
        push(
            &mut out,
            "EvidenceContent",
            &EvidenceContent {
                claim_id: id,
                kind,
                reference: Some("ref".to_owned()),
                lineage_id: Some("lineage".to_owned()),
                relation: if kind == EvidenceKind::Execution {
                    EvidenceRelation::Contradicts
                } else {
                    EvidenceRelation::Supports
                },
                source_id: source.then_some(other),
                source_hash: source.then(|| "ABCDEF".to_owned()),
            },
        );
    }
    for status in all::<SourceStatus>() {
        push(
            &mut out,
            "SourceContent",
            &SourceContent {
                relative_path: Some("docs/a.md".to_owned()),
                status,
                hash: Some("00FF".to_owned()),
                size: 1_234_567_890_123,
                indexed_at: (status == SourceStatus::Indexed).then_some(utc),
                passages: 3,
                rejection: (status == SourceStatus::Rejected).then_some(SourceRejection::TooLarge),
            },
        );
    }
    for rejection in all::<SourceRejection>() {
        push(
            &mut out,
            "SourceContent",
            &SourceContent {
                relative_path: Some("x".to_owned()),
                status: SourceStatus::Rejected,
                hash: Some(String::new()),
                size: 0,
                indexed_at: None,
                passages: 0,
                rejection: Some(rejection),
            },
        );
    }
    push(
        &mut out,
        "RetexContent",
        &RetexContent {
            event: Some("e".to_owned()),
            impact: Some("i".to_owned()),
            next_action: Some("n".to_owned()),
        },
    );
    for kind in all::<RecordKind>() {
        for status in all::<KnowledgeStatus>() {
            push(
                &mut out,
                "MemoryRecord",
                &MemoryRecord {
                    id,
                    scope_id: Some("workspace".to_owned()),
                    kind,
                    status,
                    revision: 7,
                    content_json: Some("{\"a\":1}".to_owned()),
                    provenance: Some(provenance(ActorKind::Llm, "claude", at)),
                },
            );
        }
    }
    let history =
        |sequence, previous: Option<&str>, new: &str, reason: &str, timestamp| HistoryEntry {
            sequence,
            object_id: id,
            scope_id: Some("workspace".to_owned()),
            previous_state: previous.map(str::to_owned),
            new_state: Some(new.to_owned()),
            reason: Some(reason.to_owned()),
            actor: Some("john".to_owned()),
            timestamp,
        };
    push(
        &mut out,
        "HistoryEntry",
        &history(42, None, "active", "created", at),
    );
    push(
        &mut out,
        "HistoryEntry",
        &history(43, Some("active"), "invalidated", "why", utc),
    );
    for level in all::<ConfidenceLevel>() {
        push(
            &mut out,
            "Confidence",
            &Confidence {
                level,
                reasons: vec!["a".to_owned(), "b".to_owned()],
                independent_origins: 2,
            },
        );
    }
    out
}

#[test]
fn writes_match_the_oracle() {
    let golden = golden();
    let rows = golden["writes"].as_array().expect("writes");
    let ours = written();
    assert_eq!(rows.len(), ours.len());
    let mut mismatches = Vec::new();
    for (row, (kind, json)) in rows.iter().zip(&ours) {
        // The golden file keeps the line breaks of the machine that wrote it.
        let expected = row["json"].as_str().expect("json").replace("\r\n", "\n");
        if row["type"] != *kind || expected != json.replace("\r\n", "\n") {
            mismatches.push(format!("{kind}:\n  expected {expected}\n  got      {json}"));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

fn read_back<T: Record + Serialize>(input: &str, offset: i16) -> Value {
    match read::<T>(input, &|_| offset) {
        Ok(value) => {
            serde_json::json!({ "written": write(&value).expect("written").replace("\r\n", "\n") })
        }
        Err(error) => serde_json::json!({ "code": error.code }),
    }
}

#[test]
fn reads_match_the_oracle() {
    let golden = golden();
    let offset = i16::try_from(golden["localOffsetMinutes"].as_i64().expect("offset"))
        .expect("an offset in minutes");
    let mut mismatches = Vec::new();
    for row in golden["reads"].as_array().expect("reads") {
        let kind = row["type"].as_str().expect("type");
        let input = row["input"].as_str().expect("input");
        // JsonException becomes invalid_storage_or_path in the CLI; a top-level null is
        // invalid_record.
        let expected = match row.get("written") {
            Some(json) => serde_json::json!({
                "written": json.as_str().expect("json").replace("\r\n", "\n")
            }),
            None if row["exception"] == "System.Text.Json.JsonException" => {
                serde_json::json!({ "code": "invalid_storage_or_path" })
            }
            None => serde_json::json!({ "code": row["code"] }),
        };
        let actual = match kind {
            "EvidenceContent" => read_back::<EvidenceContent>(input, offset),
            "ClaimContent" => read_back::<ClaimContent>(input, offset),
            "SourceContent" => read_back::<SourceContent>(input, offset),
            "RetexContent" => read_back::<RetexContent>(input, offset),
            "MemoryRecord" => read_back::<MemoryRecord>(input, offset),
            "HistoryEntry" => read_back::<HistoryEntry>(input, offset),
            other => panic!("unknown type {other}"),
        };
        if actual != expected {
            mismatches.push(format!(
                "{kind} {input}:\n  expected {expected}\n  got      {actual}"
            ));
        }
    }
    assert!(mismatches.is_empty(), "{}", mismatches.join("\n"));
}

mod never_panic {
    use proptest::prelude::*;
    use sermofur_core::records::*;

    fn read_all(text: &str) {
        let offset = |_| 0;
        let _ = read::<EvidenceContent>(text, &offset);
        let _ = read::<ClaimContent>(text, &offset);
        let _ = read::<SourceContent>(text, &offset);
        let _ = read::<RetexContent>(text, &offset);
        let _ = read::<MemoryRecord>(text, &offset);
        let _ = read::<HistoryEntry>(text, &offset);
    }

    /// The .NET and JSON names of the members of `EvidenceKind`.
    fn names() -> Vec<&'static str> {
        EvidenceKind::NAMES
            .iter()
            .flat_map(|(dotnet, json, _)| [*dotnet, *json])
            .collect()
    }

    /// Pieces of JSON that reach every branch of the reader and of the conversions.
    fn piece() -> impl Strategy<Value = &'static str> {
        prop::sample::select(vec![
            "{",
            "}",
            "[",
            "]",
            ",",
            ":",
            "\"kind\"",
            "\"claimId\"",
            "\"size\"",
            "\"provenance\"",
            "\"timestamp\"",
            r#""\ud800""#,
            r#""\udc00\ud800""#,
            "\"source_code, Execution\"",
            "\" , \"",
            "null",
            "true",
            "-0",
            "1e2",
            "99999999999999999999",
            "\"2026-01-02\"",
            "\"0f8fad5b-d9cb-469f-a165-70867728950e\"",
            " ",
        ])
    }

    proptest! {
        #[test]
        fn arbitrary_text_never_panics(text in r"\PC{0,256}") {
            read_all(&text);
        }

        #[test]
        fn assembled_json_never_panics(pieces in prop::collection::vec(piece(), 0..32)) {
            read_all(&pieces.concat());
        }

        #[test]
        fn depth_is_refused_beyond_64(n in 0usize..200) {
            let text = format!("{{\"event\":\"e\",\"x\":{}0{}}}", "[".repeat(n), "]".repeat(n));
            let result = read::<RetexContent>(&text, &|_| 0);
            prop_assert_eq!(result.is_ok(), n <= 63);
            if let Err(error) = result {
                prop_assert_eq!(error.code, "invalid_storage_or_path");
            }
        }

        #[test]
        /// Lists of real names (.NET or JSON, any case, spaces around) always read, as the
        /// OR of their members when that is a member, and write back to the same value.
        fn a_read_enumeration_writes_back_the_same(
            parts in prop::collection::vec(
                (prop::sample::select(names()), any::<bool>(), any::<bool>()),
                1..3,
            )
        ) {
            let kind = parts
                .iter()
                .map(|(name, upper, padded)| {
                    let name = if *upper { name.to_uppercase() } else { name.to_lowercase() };
                    if *padded { format!(" {name} ") } else { name }
                })
                .collect::<Vec<_>>()
                .join(",");
            let index = |name: &str| {
                EvidenceKind::NAMES
                    .iter()
                    .position(|(dotnet, json, _)| *dotnet == name || *json == name)
                    .expect("a member")
            };
            let or = parts.iter().fold(0, |value, (name, _, _)| value | index(name));
            let text = format!("{{\"kind\":\"{kind}\"}}");
            let first = read::<EvidenceContent>(&text, &|_| 0);
            prop_assert_eq!(first.is_ok(), or < EvidenceKind::NAMES.len());
            if let Ok(first) = first {
                prop_assert_eq!(first.kind, EvidenceKind::NAMES[or].2);
                let again = read::<EvidenceContent>(&write(&first).expect("written"), &|_| 0);
                prop_assert_eq!(again.expect("read back"), first);
            }
        }
    }
}
